package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.junit.jupiter.api.Test;

class LmdbNativeCostVectorNumericalTest {

	@Test
	void genericPlanFallbackDoesNotOverflowItsFiniteWorkMidpoint() {
		SlotPlan plan = mock(SlotPlan.class);
		when(plan.estimateWork(null, 0L)).thenReturn(LmdbNativeWork.exact(Double.MAX_VALUE));
		assertThat(LmdbNativeCostVectors.plan(plan, null, 0L, Feature.BATCH_ROW).expected(Feature.SCANNED_ROW))
				.isEqualTo(Double.MAX_VALUE);
	}

	@Test
	void patternWithoutAnAccessProfileDoesNotOverflowItsFiniteWorkMidpoint() {
		PatternPlan plan = mock(PatternPlan.class);
		when(plan.estimateWork(null, 0L)).thenReturn(LmdbNativeWork.exact(Double.MAX_VALUE));
		assertThat(LmdbNativeCostVectors.pattern(plan, null, 0L).expected(Feature.SCANNED_ROW))
				.isEqualTo(Double.MAX_VALUE);
	}

	@Test
	void anInfiniteRowCountRemainsUnpricedInsteadOfAbortingAdmission() {
		LmdbNativeCostVector vector = LmdbNativeCostVectors.perRow(Feature.GENERATED_ROW,
				Double.POSITIVE_INFINITY);
		assertThat(LmdbNativeStaticPrior.DEFAULT.price(vector).known()).isFalse();
	}

	@Test
	void aFactorizedPrefixWithOverflowedRowsDoesNotAbortCandidateAdmission() {
		SlotPlan plan = mock(SlotPlan.class);
		when(plan.estimateWork(null, 0L)).thenReturn(LmdbNativeWork.exact(1D));
		when(plan.estimateRows(null, 0L)).thenReturn(Double.MAX_VALUE);
		LmdbNativeCostVector vector = LmdbNativeCostVectors.factorizedRows(new SlotPlan[] { plan, plan, plan }, 3,
				new LmdbNativeCostVectors.BranchRole[0], Double.NaN, null, 0L);
		assertThat(LmdbNativeStaticPrior.DEFAULT.price(vector).known()).isFalse();
	}

	@Test
	void anEnumeratedFactorizedBranchSaturatesItsRowProducts() {
		SlotPlan plan = mock(SlotPlan.class);
		when(plan.producedMask()).thenReturn(1L);
		when(plan.estimateWork(null, 0L)).thenReturn(LmdbNativeWork.exact(1D));
		when(plan.estimateWork(null, 1L)).thenReturn(LmdbNativeWork.exact(1D));
		when(plan.estimateRows(null, 0L)).thenReturn(Double.MAX_VALUE);
		when(plan.estimateRows(null, 1L)).thenReturn(Double.MAX_VALUE);
		LmdbNativeCostVector vector = LmdbNativeCostVectors.factorizedRows(new SlotPlan[] { plan, plan }, 1,
				new LmdbNativeCostVectors.BranchRole[] { LmdbNativeCostVectors.BranchRole.ENUM },
				Double.NaN, null, 0L);
		assertThat(LmdbNativeStaticPrior.DEFAULT.price(vector).known()).isFalse();
	}

	@Test
	void aJoinChainWithAnOverflowedPrefixDoesNotAbortCandidateAdmission() {
		SlotPlan plan = mock(SlotPlan.class);
		when(plan.estimateWork(null, 0L)).thenReturn(LmdbNativeWork.exact(1D));
		when(plan.estimateRows(null, 0L)).thenReturn(Double.MAX_VALUE);
		LmdbNativeCostVector vector = LmdbNativeCostVectors.chain(new SlotPlan[] { plan, plan, plan }, 3,
				null, 0L, Feature.BATCH_ROW);
		assertThat(vector.high(Feature.SCANNED_ROW)).isGreaterThanOrEqualTo(LmdbNativeCostQuote.UNBOUNDED_COUNT);
	}
}
